def is_valid(s):
    balance = 0
    for c in s:
        balance += 1 if c == '(' else -1
        if balance < 0:
            return False
    return balance == 0

def longest_valid_parentheses(s):
    n = len(s)
    max_len = 0
    for i in range(n):
        for j in range(i + 2, n + 1, 2):                                   # only EVEN lengths can possibly be valid
            if is_valid(s[i:j]):
                max_len = max(max_len, j - i)
    return max_len


