    stack = [-1]                                                            # a "base" sentinel: the index just BEFORE the current valid run
    max_len = 0
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)                                                # remember this opening bracket's position
        else:
            stack.pop()                                                    # try to match this closing bracket against the most recent open
            if not stack:
                stack.append(i)                                            # nothing to match: this ')' becomes the NEW base
            else:
                max_len = max(max_len, i - stack[-1])                      # the current valid run spans from just after the new top to here
    return max_len


