import java.util.*;

public class Main {
    int longestValidParentheses(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);                                                                 // a "base" sentinel: the index just BEFORE the current valid run
        int maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);                                                            // remember this opening bracket's position
            } else {
                stack.pop();                                                               // try to match this closing bracket against the most recent open
                if (stack.isEmpty()) {
                    stack.push(i);                                                            // nothing to match: this ')' becomes the NEW base
                } else {
                    maxLen = Math.max(maxLen, i - stack.peek());                              // the current valid run spans from just after the new top to here
                }
            }
        }
        return maxLen;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.longestValidParentheses(")()())"));
    }
}

